def encodeOrDecode(operation: int, message: str, key: int) -> str:
    digits = [int(c) for c in str(key)]
    if operation not in (1, 2) or key <= 0 or 0 in digits:
        return "-1"  # 0 会让字符消失，解码无法还原，按非法输入处理
    if operation == 1:
        out = []
        for i, ch in enumerate(message):
            out.append(ch * digits[i] if i < len(digits) else ch)
        return "".join(out)
    out, pos = [], 0
    for d in digits:
        if pos >= len(message):
            break                                  # 消息先结束
        run = message[pos:pos + d]
        if len(run) < d or run != run[0] * d:      # 重复次数对不上
            return "-1"
        out.append(run[0])
        pos += d
    out.append(message[pos:])                      # key 用完后剩余字符原样保留
    return "".join(out)
